const c = $('Konfiguration [Edit Fields]').first().json;
const namen = String(c.dokumente).split(',').map(s => s.trim()).filter(Boolean);
if (namen.length === 0) throw new Error('Keine Dokumente in der Konfiguration');
return namen.map((n, i) => ({ json: {
  dokument: n,
  datei: n + '.md',
  url: c.raw_basis + '/' + n + '.md',
  stand: c.commit,
  nr: i + 1,
  von: namen.length
} }));

const kfg = $('Konfiguration [Edit Fields]').first().json;
const erwartet = String(kfg.dokumente).split(',').map(s => s.trim()).filter(Boolean);
const alle = $input.all().map(i => i.json);
const fehler = [];
for (const d of erwartet) {
  const z = alle.find(a => a.dokument === d);
  if (!z) fehler.push(d + ': nicht verarbeitet');
  else if (!(z.stuecke_gebildet > 0)) fehler.push(d + ': 0 Stücke');
}
if (fehler.length > 0) throw new Error('Einlesen unvollständig: ' + fehler.join('; '));
const summe = alle.reduce((s, a) => s + a.stuecke_gebildet, 0);
return [{ json: {
  ergebnis: 'ok',
  dokumente: alle.length,
  stuecke_gesamt: summe,
  je_dokument: alle.map(a => a.dokument + ': ' + a.stuecke_gebildet).join(', '),
  embed_model: kfg.embed_model,
  embed_dims: kfg.embed_dims,
  stand: kfg.commit
} }];

// Zerlegt ein Markdown-Dokument in Stücke (Größe und Überlappung aus der Konfiguration).
// Geschnitten wird nur an Absatz, Zeile, Satzende oder Leerzeichen, jedes Stück ist ein Ausschnitt des Originals
// (wird geprüft). Vor jedes Stück kommt eine Quellzeile mit Datei und Abschnitt, sie zählt nicht zur Größe.
function zerlege(textRoh, GROESSE, UEBERLAPPUNG) {
  const text = String(textRoh).replace(/\r\n/g, '\n');
  const TRENNER = [/\n[ \t]*\n/g, /\n/g, /(?<=[.!?:;])[ \t]+/g, /[ \t]+/g];
  const einheiten = [];
  function trimmen(s, e) {
    while (s < e && /\s/.test(text[s])) s++;
    while (e > s && /\s/.test(text[e - 1])) e--;
    return [s, e];
  }
  function teilen(s, e, stufe) {
    [s, e] = trimmen(s, e);
    if (e <= s) return;
    if (e - s <= GROESSE) { einheiten.push([s, e]); return; }
    if (stufe >= TRENNER.length) {
      for (let p = s; p < e; p += GROESSE) einheiten.push([p, Math.min(e, p + GROESSE)]);
      return;
    }
    const re = new RegExp(TRENNER[stufe].source, 'g');
    const teile = [];
    let schnitt = s;
    const segment = text.slice(s, e);
    let m;
    while ((m = re.exec(segment)) !== null) {
      if (m[0].length === 0) { re.lastIndex++; continue; }
      teile.push([schnitt, s + m.index]);
      schnitt = s + m.index + m[0].length;
    }
    teile.push([schnitt, e]);
    if (teile.length === 1) { teilen(s, e, stufe + 1); return; }
    let aktStart = null, aktEnde = null;
    for (const [a, b] of teile) {
      const [ta, tb] = trimmen(a, b);
      if (tb <= ta) continue;
      if (tb - ta > GROESSE) {
        if (aktStart !== null) { einheiten.push([aktStart, aktEnde]); aktStart = null; }
        teilen(ta, tb, stufe + 1);
        continue;
      }
      if (aktStart === null) { aktStart = ta; aktEnde = tb; }
      else if (tb - aktStart <= GROESSE && stufe >= 2) { aktEnde = tb; }
      else { einheiten.push([aktStart, aktEnde]); aktStart = ta; aktEnde = tb; }
    }
    if (aktStart !== null) einheiten.push([aktStart, aktEnde]);
  }
  teilen(0, text.length, 0);
  const ueberschriften = [];
  const reH = /^(#{1,6})[ \t]+(.+)$/gm;
  let h;
  while ((h = reH.exec(text)) !== null) ueberschriften.push({ pos: h.index, titel: h[2].trim() });
  function abschnittBei(pos) {
    let t = 'Einleitung';
    for (const u of ueberschriften) { if (u.pos <= pos) t = u.titel; else break; }
    return t;
  }
  const stuecke = [];
  let i = 0;
  while (i < einheiten.length) {
    let j = i;
    while (j + 1 < einheiten.length && einheiten[j + 1][1] - einheiten[i][0] <= GROESSE) j++;
    const von = einheiten[i][0], bis = einheiten[j][1];
    stuecke.push({ von, bis, text: text.slice(von, bis), abschnitt: abschnittBei(von) });
    if (j + 1 >= einheiten.length) break;
    let k = j + 1;
    for (let c = i + 1; c <= j; c++) { if (einheiten[j][1] - einheiten[c][0] <= UEBERLAPPUNG) { k = c; break; } }
    i = k;
  }
  return { text, stuecke };
}

const kfg = $('Konfiguration [Edit Fields]').first().json;
const doc = $input.first().json;
const { text, stuecke } = zerlege(doc.text, Number(kfg.chunk_size), Number(kfg.chunk_overlap));
if (text.length < 500) throw new Error('Dokument zu kurz oder leer (' + text.length + ' Zeichen): ' + doc.dokument);
if (stuecke.length === 0) throw new Error('0 Stücke für ' + doc.dokument);
return stuecke.map((s, i) => {
  if (text.slice(s.von, s.bis) !== s.text) throw new Error('Stück ' + i + ' ist kein Ausschnitt des Originals: ' + doc.dokument);
  if (s.text.length > Number(kfg.chunk_size)) throw new Error('Stück ' + i + ' zu lang (' + s.text.length + '): ' + doc.dokument);
  const vorher = i > 0 ? stuecke[i - 1] : null;
  return { json: {
    text: 'Quelle: ' + doc.datei + ', Abschnitt: ' + s.abschnitt + '\n' + s.text,
    dokument: doc.dokument,
    datei: doc.datei,
    stand: doc.stand,
    abschnitt: s.abschnitt,
    chunk_index: i,
    chunk_total: stuecke.length,
    zeichen_netto: s.text.length,
    ueberlappung_zeichen: vorher ? Math.max(0, vorher.bis - s.von) : 0,
    zeichen_original: text.length
  }, pairedItem: { item: 0 } };
});

const gebildet = $('In Stücke schneiden [Code]').all();
const erste = gebildet.length > 0 ? gebildet[0].json : {};
return [{ json: {
  dokument: erste.dokument,
  datei: erste.datei,
  stuecke_gebildet: gebildet.length,
  eintraege_vom_speicher_knoten: $input.all().length,
  zeichen_original: erste.zeichen_original,
  eingelesen_am: new Date().toISOString()
} }];
